    (F : bvmap 5 word) fc (m : mem),
  ARegistry LB m r owner first 0 ->
  ati_ok m AL_TYPEID_CONFIG ATI_NAME_CONFIG ->
  ASvcChain m first L -> find_svc AL_TYPEID_CONFIG 0 ATI_NAME_CONFIG L = fsv -> 0 < fsv < 2^64 -> fsv mod 8 = 0 ->
  Forall (fun e => se_addr e + 48 <= r \/ r + SZ_REG <= se_addr e) L ->
  0 <= owner < 2^64 ->
  stk bsegs m lo (bv_unsigned sp) -> lo + AUSVC_STACK <= bv_unsigned sp -> aceil <= lo ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv bsegs m ->
  bv_unsigned sp mod 16 = 0 -> ACONST m -> stack0 m lo shi -> bv_unsigned sp <= shi ->
  evt bsegs (do_use_service_found_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LB r owner first fsv lo shi m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz r) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_B_USE_SVC_CONFIG) fc None m (seg_rom bsegs)).
